        height: box,
        display: 'block',
        overflow: 'visible',
        pointerEvents: 'none',
        strokeWidth,
      }}
      viewBox={`0 0 ${box} ${box}`}
    >
      {Array.from({ length: segCount }).map((_, i) => {
        const t = i / Math.max(1, segCount - 1);
        const deg = startDeg + (endDeg - startDeg) * t;
        const th = toRad(deg);

        const ux = Math.cos(th);
        const uy = Math.sin(th);

        const c0x = cx + ux * rStart;
        const c0y = cy + uy * rStart;
        const c1x = cx + ux * rEnd;
        const c1y = cy + uy * rEnd;

        return (
          <motion.line
            key={i}
            x1={c0x - ux * (lenStart / 2)}
            y1={c0y - uy * (lenStart / 2)}
            x2={c0x + ux * (lenStart / 2)}
            y2={c0y + uy * (lenStart / 2)}
            initial={{ pathLength: 1, scale: 1 }}
            animate={{
              x1: [
                c0x - ux * (lenStart / 2),
                c1x - ux * (lenEnd / 2),
                c1x - ux * (lenEnd / 2),
              ],
              y1: [
                c0y - uy * (lenStart / 2),
                c1y - uy * (lenEnd / 2),
                c1y - uy * (lenEnd / 2),
              ],
              x2: [
                c0x + ux * (lenStart / 2),
                c1x + ux * (lenEnd / 2),
                c1x + ux * (lenEnd / 2),
              ],
              y2: [
                c0y + uy * (lenStart / 2),
                c1y + uy * (lenEnd / 2),
                c1y + uy * (lenEnd / 2),
              ],
              pathLength: [1, 0.5, 0.5],
              scale: [1, 1, 0],
            }}
            transition={{
              duration: d,
              ease: 'easeInOut',
              times: [0, 0.7, 1],
            }}
            stroke={item.color}
          />
        );
      })}
    </motion.svg>
  );
}

function Particles({ item }: { item: Item }) {
  const d = item.duration / 1000;

  const count = 6;
  const radius = item.size * 0.35;
  const r0 = Math.max(item.size * 0.025, 2);

  const half = radius + r0 * 2;
  const box = half * 2;
  const cx = half,
    cy = half;

  const angleStep = (2 * Math.PI) / count;

  return (
    <motion.svg
      style={{
        position: 'fixed',
        left: item.x - half,
        top: item.y - half,
        width: box,
        height: box,
        display: 'block',
        overflow: 'visible',
        pointerEvents: 'none',
      }}
      viewBox={`0 0 ${box} ${box}`}
    >
      {Array.from({ length: count }).map((_, i) => {
        const angle = i * angleStep;
        const x = Math.cos(angle) * radius;
        const y = Math.sin(angle) * radius;

        return (
          <motion.circle
            key={i}
            cx={cx}
            cy={cy}
            r={r0}
            fill={item.color}
            initial={{ scale: 0, opacity: 0 }}
            animate={{
              cx: cx + x,
              cy: cy + y,
              scale: [0, 1, 0],
              opacity: [0, 1, 0],
            }}
            transition={{
              duration: d,
              delay: i * (d * 0.08),
              ease: 'easeOut',
            }}
          />
        );
      })}
    </motion.svg>
  );
}

